  storyId: string;
  providerAgent: string;
  lane: string;
  reviewRunId: string;
  conclusion: 'pass' | 'findings';
  note?: string;
  findings?: ManagedReviewFinalEnvelopeFinding[];
  readManifest: ManagedReviewFinalEnvelopeReadManifest;
}

export type ManagedReviewFinalEnvelopeClassification =
  | { kind: 'ordinary' }
  | { kind: 'malformed' }
  | { kind: 'valid'; envelope: ManagedReviewFinalEnvelopeRecord };

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every(item => typeof item === 'string');
}

/** Shared strict validator consumed at adapter, persistence, and import/gate boundaries. */
export function isStrictManagedReviewFindingProposal(value: unknown): value is ManagedReviewFinalEnvelopeFinding {
  if (!isPlainRecord(value)) return false;
  const allowed = new Set(['desc', 'severity', 'category', 'files', 'evidenceState', 'uncertaintyReason']);
  if (Object.keys(value).some(key => !allowed.has(key))) return false;
  if (typeof value.desc !== 'string' || value.desc.trim().length === 0) return false;
  if (!['critical', 'high', 'medium', 'low'].includes(String(value.severity))) return false;
  if (!['happy', 'edge', 'adversarial', 'missing'].includes(String(value.category))) return false;
  if (value.files !== undefined
    && (!isStringArray(value.files) || value.files.some(file => file.trim().length === 0))) return false;
  if (value.evidenceState !== undefined
    && value.evidenceState !== 'suspected'
    && value.evidenceState !== 'verified') return false;
  if (value.evidenceState === 'suspected') {
    if (typeof value.uncertaintyReason !== 'string' || value.uncertaintyReason.trim().length === 0) return false;
  } else if (value.uncertaintyReason !== undefined) {
    return false;
  }
  return true;
}

/**
 * Classify one provider-owned final assistant text without treating ordinary
 * Codex progress messages as proposal candidates. A message that explicitly
 * names the managed proposal schema remains fail-closed when malformed; valid
 * envelopes receive a second semantic/provenance validation in the managed
 * worker before any immutable proposal is written.
 */
export function classifyManagedReviewFinalEnvelope(text: string): ManagedReviewFinalEnvelopeClassification {
  const trimmed = text.trim();
  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
      ? { kind: 'malformed' }
      : { kind: 'ordinary' };
  }
  if (!isPlainRecord(parsed)) return { kind: 'ordinary' };
  if (parsed.schemaVersion !== MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION) {
    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
      ? { kind: 'malformed' }
      : { kind: 'ordinary' };
  }

  const conclusion = parsed.conclusion;
  const allowed = new Set([
    'schemaVersion', 'storyId', 'providerAgent', 'lane', 'reviewRunId', 'conclusion',
    'readManifest', 'readLog', 'readDiagnostics', conclusion === 'pass' ? 'note' : 'findings',
  ]);
  const readManifest = parsed.readManifest;
  const validReadManifest = isPlainRecord(readManifest)
    && isStringArray(readManifest.filesReadFully)
    && isStringArray(readManifest.filesTriagedByName)
    && (readManifest.scanEscalationReason === null || typeof readManifest.scanEscalationReason === 'string')
    && (readManifest.candidateSpecSetDigest === undefined || typeof readManifest.candidateSpecSetDigest === 'string')
    && (readManifest.corpusDigest === undefined || typeof readManifest.corpusDigest === 'string');
  const validConclusionPayload = conclusion === 'pass'
    ? typeof parsed.note === 'string'
    : conclusion === 'findings'
      && Array.isArray(parsed.findings)
      && parsed.findings.length > 0
      && parsed.findings.every(isStrictManagedReviewFindingProposal);
  if (Object.keys(parsed).some(key => !allowed.has(key))
    || typeof parsed.storyId !== 'string'
    || typeof parsed.providerAgent !== 'string'
    || typeof parsed.lane !== 'string'
    || typeof parsed.reviewRunId !== 'string'
    || !validReadManifest
    || !validConclusionPayload
    || (parsed.readLog !== undefined && !isPlainRecord(parsed.readLog))
    || (parsed.readDiagnostics !== undefined && !Array.isArray(parsed.readDiagnostics))) {
    return { kind: 'malformed' };
  }
  return { kind: 'valid', envelope: parsed as ManagedReviewFinalEnvelopeRecord };
}

export class FinalAssistantResultScanner {
  private partial = '';
  private skippingCandidate = false;
  private result: string | null = null;
  private candidateCount = 0;
  private candidateTruncated = false;

  constructor(
    private readonly host: HostRunHost | undefined,
    private readonly cap: number = HOST_RUN_FINAL_ASSISTANT_RESULT_CAP,
  ) {}

  push(text: string): void {
    if ((this.host !== 'codex' && this.host !== 'claude') || text.length === 0) return;
    let data = text;
    while (data.length > 0) {
      const nl = data.indexOf('\n');
      if (nl === -1) {
        if (this.skippingCandidate) return;
        if (this.partial.length + data.length > this.cap) {
          this.markOversizeCandidate(`${this.partial}${data.slice(0, Math.max(0, this.cap - this.partial.length))}`);
          this.partial = '';
          this.skippingCandidate = true;
          return;
        }
        this.partial += data;
        return;
      }
      const segment = data.slice(0, nl);
    projectRootHash: spec.projectRootHash,
    profile: spec.profile,
    promptDigest: owner.promptDigest,
    reviewBinding: spec.reviewBinding ?? null,
  };
}

/** Resolve the immutable Story subject used by the CLI ownership gate. */
export function managedHostRunStoryIdForOwnership(root: string, runId: string): string | null {
  const paths = pathsFor(root, runId);
  if (!existsSync(paths.spec) || !existsSync(paths.owner)) return null;
  const specText = readFileSync(paths.spec, 'utf8');
  const spec = JSON.parse(specText) as ManagedHostRunSpec;
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  if (spec.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || owner.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || spec.runId !== runId
    || owner.runId !== runId
    || owner.specDigest !== sha256(specText)) {
    throw new Error(`managed host run ${runId}: immutable ownership subject binding mismatch`);
  }
  return typeof spec.storyId === 'string' && spec.storyId.trim().length > 0 ? spec.storyId.trim() : null;
}

type ManagedReviewFinalProposalInput = Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;

function parseManagedReviewFinalProposal(result: HostRunResult): ManagedReviewFinalProposalInput {
  if (result.finalAssistantResultTruncated) {
    throw new Error('managed_review_final_result_oversize');
  }
  if (result.finalAssistantResultCount > 1) {
    throw new Error('managed_review_final_result_multiple');
  }
  if (result.finalAssistantResultCount !== 1 || result.finalAssistantResult === null) {
    throw new Error('managed_review_final_result_missing');
  }
  const classification = classifyManagedReviewFinalEnvelope(result.finalAssistantResult);
  if (classification.kind !== 'valid') throw new Error('managed_review_final_result_malformed');
  const envelope = classification.envelope;
  const conclusion = envelope.conclusion;
  return {
    storyId: envelope.storyId,
    providerAgent: envelope.providerAgent,
    lane: envelope.lane,
    reviewRunId: envelope.reviewRunId,
    conclusion,
    ...(conclusion === 'pass' ? { note: envelope.note as string | undefined } : {
      findings: envelope.findings as ManagedReviewEvidenceFindingProposal[] | undefined,
    }),
    readManifest: envelope.readManifest as ReviewerReadManifest,
    ...(envelope.readLog !== undefined ? { readLog: envelope.readLog as ReviewerReadLogEvidence } : {}),
    ...(envelope.readDiagnostics !== undefined ? { readDiagnostics: envelope.readDiagnostics as ReviewerReadDiagnostic[] } : {}),
  };
}

export function writeManagedReviewEvidenceProposal(args: {
  root: string;
  runId: string;
  proposal: Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;
  environment?: NodeJS.ProcessEnv;
  providerInvocationPid?: number;
  providerInvocationAttestation?: ManagedReviewProposalInvocationAttestation;
}): ManagedReviewEvidenceProposal {
  const paths = pathsFor(args.root, args.runId);
  const spec = readJson<ManagedHostRunSpec>(paths.spec);
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  const environment = args.environment ?? process.env;
  if (args.providerInvocationPid === undefined
    && args.providerInvocationAttestation === undefined
    && environment.LATTICE_MANAGED_HOST_RUN_ID !== args.runId) {
    throw new Error('managed_review_proposal_set: active managed-run capability is missing or mismatched');
  }
  if (readTerminal(paths) || snapshot.state !== 'running') {
    throw new Error('managed_review_proposal_set: proposal is accepted only while the managed provider run is active');
  }
  } else if (conclusion === 'findings') {
    if (findings.length === 0 || note.length > 0) {
      throw new Error('managed_review_proposal_set: findings conclusion requires at least one finding and no pass note');
    }
  } else {
    throw new Error('managed_review_proposal_set: conclusion must be pass or findings');
  }
  const normalizedFindings = findings.map((finding, index) => {
    if (!isStrictManagedReviewFindingProposal(finding)) {
      throw new Error(`managed_review_proposal_set: findings[${index}] must match the strict managed finding schema`);
    }
    return {
      ...finding,
      desc: finding.desc.trim(),
      ...(finding.files ? { files: [...new Set(finding.files.map(value => value.trim()).filter(Boolean))].sort() } : {}),
    };
  });
  const proposal: ManagedReviewEvidenceProposal = {
    schemaVersion: 'lattice.managed_review_evidence_proposal.v1',
    runId: args.runId,
    storyId: spec.storyId,
    providerAgent: spec.agentType,
    lane: spec.lane,
    reviewRunId: spec.reviewRunId,
    authoredAt: new Date().toISOString(),
    conclusion,
    ...(conclusion === 'pass' ? { note } : { findings: normalizedFindings }),
    readManifest: normalizeReviewerReadManifest(args.proposal.readManifest),
    ...(args.proposal.readLog ? { readLog: normalizeReviewerReadLogEvidence(args.proposal.readLog) } : {}),
    ...(args.proposal.readDiagnostics ? { readDiagnostics: normalizeReviewerReadDiagnostics(args.proposal.readDiagnostics) } : {}),
  };
  withTerminalAuthorityLock(paths, () => {
    if (readTerminal(paths)) {
      throw new Error('managed_review_proposal_set: proposal is accepted only while the managed provider run is active');
    }
    if (!writeExclusive(paths.evidenceProposal, proposal)) {
      throw new Error('managed_review_proposal_set: this run already has an immutable evidence proposal');
    }
    appendFileSync(paths.events, `${canonicalJson({
      schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
      runId: args.runId,
      at: proposal.authoredAt,
      type: 'review_evidence_proposed',
      detail: { conclusion, proposalDigest: digestFile(paths.evidenceProposal) },
    })}\n`, { encoding: 'utf8', mode: 0o600 });
  });
  return proposal;
}

export function readManagedReviewEvidenceProposal(root: string, runId: string): ManagedReviewEvidenceProposal | null {
  const paths = pathsFor(root, runId);
  return existsSync(paths.evidenceProposal) ? readJson<ManagedReviewEvidenceProposal>(paths.evidenceProposal) : null;
}

