export const MANAGED_HOST_RUN_DEFAULT_DEADLINE_MS = 30 * 60 * 1000;
export const MANAGED_HOST_RUN_MAX_DEADLINE_MS = 24 * 60 * 60 * 1000;
export const MANAGED_HOST_RUN_CLAIM_TIMEOUT_MS = 5_000;
